WITH src AS (SELECT * FROM inventory WHERE product_id = 2 AND product_id = 9 AND last_restock > '2024-02-01'), summary AS (SELECT DATE_TRUNC('MONTH', last_restock) AS last_restock_month, product_id, MAX(quantity) - MIN(quantity) AS quantity_range FROM src GROUP BY DATE_TRUNC('MONTH', last_restock), product_id) SELECT last_restock_month, product_id, quantity_range FROM summary ORDER BY quantity_range, last_restock_month DESC;
